		cur += (0xff & p->tcfp_keys[i].offmask) >> p->tcfp_keys[i].shift;

		/* Each key touches 4 bytes starting from the computed offset */
		p->tcfp_off_max_hint = max(p->tcfp_off_max_hint, cur + 4);
